async function seedStocks() {
  console.log(`Starting expanded database seeding of ${FULL_STOCKS_LIST.length} stocks to Firestore...`);
  const batch = db.batch();
  
  for (const stock of FULL_STOCKS_LIST) {
    const docRef = db.collection('stocks').doc(stock.id);
    batch.set(docRef, {
      ...stock,
      lastUpdated: new Date().toISOString()
    });
    console.log(`Seeding: ${stock.name} (${stock.id})`);
  }
  
  await batch.commit();
  console.log('Successfully completed seeding of all stocks!');
}

seedStocks().catch(console.error);
